import json
import os
import shutil

from framework_evidence import run_tool

candidate_names = ["dumpcap", "tshark", "tcpdump"]
path_value = os.environ.get("PATH", "")
path_directories = path_value.split(os.pathsep) if path_value else []
found = {}

for name in candidate_names:
    resolved = shutil.which(name)
    if resolved:
        found[name] = resolved

# The previous execution observed this exact executable path, so check it even
# if the current PATH does not resolve its basename.
if "dumpcap" not in found and os.path.isfile("/usr/bin/dumpcap") and os.access("/usr/bin/dumpcap", os.X_OK):
    found["dumpcap"] = "/usr/bin/dumpcap"

report = {
    "sources_checked": {
        "exposed_tool_inventory": {
            "available_listed_commands": ["nmap", "msfconsole", "git", "curl", "wget"],
            "inventory_is_exhaustive": False,
            "unlisted_tool_status": "unverified",
        },
        "command_search_paths": path_directories,
        "capture_candidate_names_checked": candidate_names,
        "observed_interfaces_from_environment": ["lo", "eth0"],
        "previous_evidence": " /usr/bin/dumpcap -D timed out; this check does not repeat that interface-list command.",
    },
    "candidate_paths": found,
    "tool_results": [],
}

for name, executable in found.items():
    help_result = run_tool([executable, "-h"])
    report["tool_results"].append({
        "candidate": name,
        "path": executable,
        "probe": "help",
        "argv": [executable, "-h"],
        "envelope": help_result,
    })
    for interface in ["lo", "eth0"]:
        interface_argv = [executable, "-i", interface, "-L"]
        interface_result = run_tool(interface_argv)
        report["tool_results"].append({
            "candidate": name,
            "path": executable,
            "probe": "interface_link_layer_and_access",
            "interface": interface,
            "argv": interface_argv,
            "envelope": interface_result,
        })

print(json.dumps(report, ensure_ascii=False, default=str))

