import json
import os
import shutil
import subprocess

candidates = ["dumpcap", "tshark", "tcpdump", "wireshark", "termshark", "pktmon"]
path_value = os.environ.get("PATH", "")
path_entries = path_value.split(os.pathsep) if path_value else []
timeout_path = shutil.which("timeout")
results = []

for name in candidates:
    found = shutil.which(name)
    item = {
        "name": name,
        "path_search_result": found,
        "present_on_path": found is not None,
        "executable": bool(found and os.access(found, os.X_OK)),
        "checks": []
    }
    if found and name in ("dumpcap", "tshark", "tcpdump"):
        if timeout_path:
            for option in ("-v", "-h"):
                command = [timeout_path, "--signal=TERM", "4s", found, option]
                completed = subprocess.run(
                    command,
                    capture_output=True,
                    text=True,
                    timeout=6
                )
                item["checks"].append({
                    "argv": command,
                    "returncode": completed.returncode,
                    "stdout": completed.stdout,
                    "stderr": completed.stderr,
                    "timeout_wrapper_used": True
                })
        else:
            item["checks"].append({
                "invocation_skipped": True,
                "reason": "No timeout executable was found on PATH; candidate invocation was not run."
            })
    results.append(item)

print(json.dumps({
    "sources_checked": {
        "runtime_tool_inventory": {
            "source": "task-supplied execution_environment.tools and commands",
            "listed_capture_tool": False,
            "inventory_is_exhaustive": False,
            "meaning": "The supplied inventory does not establish that unlisted tools are absent."
        },
        "command_search": {
            "source": "process PATH",
            "path_entries": path_entries,
            "candidates_checked": candidates,
            "timeout_command": timeout_path
        },
        "prior_observations": [
            "A prior generated check invoked /usr/bin/dumpcap -D and timed out after 4 seconds without interface output.",
            "Other prior discovery attempts timed out without output; they do not establish tool absence."
        ]
    },
    "candidates": results,
    "observed_interfaces_from_supplied_environment": ["lo", "eth0"],
    "interface_and_access_assessment": {
        "interface_enumeration_performed": False,
        "capture_performed": False,
        "capture_permissions_confirmed": False,
        "interface_support": "Unresolved by this discovery. Version/help output may describe interface-selection options but does not prove access to lo or eth0.",
        "reason": "Interface enumeration previously timed out; this check avoids repeating it and does not perform a capture."
    }
}, indent=2))

