import json
import subprocess
import sys

access_probe = "import socket; s=socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.htons(3)); print('socket_create=success', flush=True); s.close()"
bind_probe = "import socket,sys; s=socket.socket(socket.AF_PACKET, socket.SOCK_RAW, socket.htons(3)); print('socket_create=success', flush=True); s.bind((sys.argv[1], 0)); print('bind=success', flush=True); s.close()"

def run_probe(code, interface=None):
    args = [sys.executable, "-c", code]
    if interface is not None:
        args.append(interface)
    result = subprocess.run(args, capture_output=True, text=True)
    return {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr,
    }

access_result = run_probe(access_probe)
interface_results = {}
for interface in ("eth0", "lo"):
    result = run_probe(bind_probe, interface)
    if result["returncode"] == 0 and "bind=success" in result["stdout"]:
        result["outcome"] = "socket creation and interface binding succeeded"
    elif "socket_create=success" in result["stdout"]:
        result["outcome"] = "socket creation succeeded; interface binding failed or was inconclusive"
    else:
        result["outcome"] = "socket creation failed; interface binding was not reached"
    interface_results[interface] = result

if access_result["returncode"] == 0 and "socket_create=success" in access_result["stdout"]:
    access_result["outcome"] = "packet-socket creation succeeded"
else:
    access_result["outcome"] = "packet-socket creation failed; inspect stderr for the reported cause"

print(json.dumps({
    "method": "Python standard-library AF_PACKET SOCK_RAW with ETH_P_ALL",
    "socket_access_test": access_result,
    "interface_binding_tests": interface_results,
    "limitations": "Binding success establishes capability only; this probe does not capture or verify traffic. Raw subprocess output is retained."
}, indent=2))

